def _m(mid, series, table, unit, fmt, rel, ko, en, external=None):
    d = dict(id=mid, series=series, table=table, unit=unit, fmt=fmt, reliability=rel, ko=ko, en=en)
    if external:
        d["external"] = external
    return d


